SELECT id, order_id, COUNT(unit_price) OVER w_ordered AS last3_count_unit_price, AVG(unit_price) OVER w_ordered AS last3_avg_unit_price, MAX(unit_price) OVER w_ordered AS last3_max_unit_price, ROW_NUMBER() OVER w_ordered_2 AS event_seq FROM order_items WINDOW w_ordered AS (PARTITION BY order_id ORDER BY unit_price, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_ordered_2 AS (PARTITION BY product_id ORDER BY quantity, id)
